int q;
map<long long,long long>lu;
map<long long,long long>::iterator iter;

void jiaqian(long long u,long long v,long long w)
{
    while(u!=v)
    {
        if(u>v)
        {
            lu[u]+=w;
            u/=2;
        }
        else
        {
            lu[v]+=w;
            v/=2;
        }
    }
}

long long fee(long long u,long long v)
{
    long long tmp=0;
    while(u!=v)
    {
        if(u>v)
        {
            iter=lu.find(u);
            if(iter!=lu.end()) tmp+=iter->second;
            u/=2;
        }
        else
        {
            iter=lu.find(v);
            if(iter!=lu.end()) tmp+=iter->second;
            v/=2;
        }
    }
    return tmp;
}

