string sum(string s , string t){
    if (s.length() < t.length()) swap(s , t);
    string ans = s;
    bool pl = false;
    int i = s.length() - 1 , j = t.length() - 1;
    while(j >= 0){
        ans[i] += t[j] - '0';
        if (pl) ans[i]++;
        pl = false;
        if (ans[i] > '9') ans[i] -= 10 , pl = true;
        i-- , j--;
    }
    while(i >= 0){
        if (pl) ans[i]++;
        pl = false;
        if (ans[i] > '9') ans[i] -= 10 , pl = true;
        i--;
    }
    if (pl && i < 0) ans = '1' + ans;
    return ans;
}
