void solve() {
  int n, m;
  cin >> n >> m;
  vector<vector<int>> a(n, vector<int>(m));
  set<vector<int>> st;
  auto inv = [](const vector<int>& v) {
    vector<int> ans(v.size());
    for (int i = 0; i < v.size(); ++i) {
      ans[v[i]] = i;
    }
    return ans;
  };
  for (auto& v : a) {
    for (auto& x : v) cin >> x, x--;
    st.insert(inv(v));
  }
  auto calc = [&](const vector<int>& x, const vector<int>& y) {
    int ans = 0;
    for (int i = 0; i < x.size(); ++i) {
      if (x[i] == y[i]) ans++;
      else break;
    }
    return ans;
  };
  for (auto& v : a) {
    auto it = st.lower_bound(v);
    int ans = 0;
    if (it != st.end()) ans = max(ans, calc(v, *it));
    if (it != st.begin()) ans = max(ans, calc(v, *prev(it)));
    cout << ans << " ";
  }
  cout << "\n";
}

