    if(n%2==p)it[x]=it[x*2]^it[x*2+1];
    else it[x]=it[x*2]|it[x*2+1];
}
void bo(int x,int l,int r,int i,int u,int p)
{
    if(l==r)
    {
        it[x]=u;
        return;
    }
    if(l<=i && i<=(l+r)/2)bo(x*2,l,(l+r)/2,i,u,(p+1)%2);
    if((l+r)/2+1<=i && i<=r)bo(x*2+1,(l+r)/2+1,r,i,u,(p+1)%2);
    if(n%2==p)it[x]=it[x*2]^it[x*2+1];
    else it[x]=it[x*2]|it[x*2+1];
}
