long long gao(int *begin, int *end, int l, int r)
{
	// empty
	if (end == begin)
		return a;
	// not empty
	long long ans = 1ll * (end - begin) * (r - l) * b;
	if (r - l == 1)
		return ans;
	int m = l + (r - l) / 2;
	int *p;
	for (p = begin; p != end && *p < m; p++);
	ans = min(ans, gao(begin, p, l, m) + gao(p, end, m, r));
	return ans;
}

