int mod_sum_pow(long long a, int b, long long c, int mod) {
  long long d = 1;
  long long result = 0;
  for (; b > 0; b /= 2) {
    if (b % 2 != 0) {
      result = (result + a * d) % mod;
      d = d * c % mod;
    }
    a = (a + a * c) % mod;
    c = c * c % mod;
  }
  return result;
}

