using i64 = long long;

void solveOne() {
  i64 n, m;
  std::cin >> n >> m;
  std::vector<std::pair<i64, i64>> a(n);
  for (auto& [p, c] : a) {
    std::cin >> p;
  }
  for (auto& [p, c] : a) {
    std::cin >> c;
  }
  std::sort(a.begin(), a.end());
  i64 ans = 0;
  for (auto& [p, c] : a) {
    ans = std::max(ans, std::min(m / p, c) * p);
  }
  auto apply = [&](i64 p, i64 c0, i64 c1) {
    i64 budget = m;
    i64 b0 = 0;
    i64 b1 = 0;
    b0 = std::min(c0, budget / p);
    budget -= b0 * p;
    b1 = std::min(c1, budget / (p + 1));
    budget -= b1 * (p + 1);
    i64 mov = std::min({b0, c1 - b1, budget});
    b0 -= mov;
    b1 += mov;
    ans = std::max(ans, p * b0 + (p + 1) * b1);
  };
  for (int i = 0; i < int(a.size()) - 1; ++i) {
    if (a[i].first + 1 == a[i + 1].first) {
      apply(a[i].first, a[i].second, a[i + 1].second);
    }
  }
  std::cout << ans << '\n';
}

