int U,D,L,R;
queue<pii> q;
int bfs(int sx,int sy){
    int sz=1;
    U=sx,D=sx,L=sy,R=sy;
    q.push(mp(sx,sy));
    v[sx][sy]=true;
    while(!q.empty()){
        pii top=q.front();
        q.pop();
        int x=top.first,y=top.second;
        for(int i=0;i<4;i++){
            int xx=x+dx[i],yy=y+dy[i];
            if(xx<1||xx>n||yy<1||yy>m) continue;
            if(s[xx][yy]!='#'||v[xx][yy]) continue;
            U=min(U,xx),D=max(D,xx);
            L=min(L,yy),R=max(R,yy);
            q.push(mp(xx,yy));
            v[xx][yy]=true;
            sz++;
        }
    }
    return sz;
}

