struct DSU{
	int fa[SIZE],size[SIZE];
	inline void add(const int&id){fa[id]=id,size[id]=1;}
	inline DSU(int _n){for(int i=1;i<=_n;i++)add(i);}
	inline int&getFa(const int&id){return fa[id]^id?fa[id]=getFa(fa[id]):fa[id];}
	inline int&operator[](const int&id){return getFa(id);}
	inline void unite(int u,int v){
		u=getFa(u),v=getFa(v);
		if(u!=v){
//			if(size[u]<size[v])std::swap(u,v);
			if(u>v)std::swap(u,v);
			fa[v]=u,size[u]+=size[v],size[v]=0;
		}
	}
};

