lol pw(lol x, lol y) { lol a = 1; for (lol i = 0; i < y; i++) a *= x; return a;}
lol square_root(lol x) {
    if(x==0)return 0;
    lol low = 1, high = 3e9, ans = 1; while (low <= high) {
        lol mid = (low + high) / 2;
        if (mid * mid <= x) {ans = mid; low = mid + 1;} else high = mid - 1;
    } return ans;
}

bool isPrime(lol n)
{
    if (n <= 1)return false; if (n <= 3)return true; if (n % 2 == 0 || n % 3 == 0)return false;
    for (int i = 5; i * i <= n; i = i + 6)if (n % i == 0 || n % (i + 2) == 0)return false;
    return true;
}

