lol bigmod(lol b,lol p,lol m){
    if(p==0)return 1;
    if(p%2==1){
        lol l=b%m;
        lol r=bigmod(b,p-1,m);
        return (l*r)%m;
    }
    else{
        lol l=bigmod(b,p/2,m);
        return(l*l)%m;
    }
}
