	for (int i=1;i<=n;i++) scanf("%d",&val[i]);
	for (int i=1;i<=n-1;i++)
	{
		int s,t;
		scanf("%d%d",&s,&t);
		add_edge(s,t);
	}
	find(1,-1);
	if (ans==NA) printf("Impossible\n");
	else printf("%I64d\n",ans);
	return 0;
}

