	if( used[x] ) sz[x] = 1; else sz[x] = 0;
	ez(i,x) {
		if( to == f ) continue;
		dfs(to,x); sz[x] += sz[to]; dis[x] += dis[to] + sz[to];
	}
}
inline void Max(int&a,int b) { if( b > a ) a = b; }

inline void solve(int x,int f,int w) {
	if( used[x] ) w++;
	int maxl = 0, tot = 0, son;
	ez(i,x) {
		if( to == f ) continue;
		if( sz[to] > maxl ) maxl = sz[to], son = to; tot += sz[to];
	}
	if( tot - maxl + w >= maxl ) return; 
	else solve(son,x,tot-maxl+w), maxl -= (tot - maxl + w), ans -= maxl; 
}

