ll bit[N];

inline int lowbit(int x)
{
    return x & (-x);
}

void add(int x,int d)
{
    //printf("add %d\n",x);
    while(x <= m)
    {
        bit[x] += d;
        x += lowbit(x);
    }
}

ll sum(int x)
{
    //printf("sum %d = ",x);
    ll ans = 0;
    while(x)
    {
        ans += bit[x];
        x -= lowbit(x);
    }
    //printf("%lld\n",ans);
    return ans;
}

inline int get(ll x)
{
    int p = lower_bound(tmp,tmp + m,x) - tmp;
    if(p >= m || tmp[p] != x) return -1;
    return p + 1;
}

void init()
{
    memset(bit,0,sizeof(bit));
    p[0] = v[0];
    for(int i = 1;i < n; ++i)
        p[i] = p[i - 1] + v[i];
    for(int i = 0;i < n; ++i)
        tmp[i] = p[i];
    tmp[n] = 0;
    sort(tmp,tmp + n + 1);
    m = unique(tmp,tmp + n + 1) - tmp;
    add(get(0),1);
}

