{
    scanf("%d%d",&n,&k);
    for(int i = 0;i < n; ++i)
        scanf("%lld",&v[i]);
    init();
    ll ans = 0;
    for(int i = 0;i < n; ++i)
    {
        ll now = 1;
        while(true)
        {
            ll x = p[i] - now;
            int pos = get(x);
            ll last = ans;
            if(pos != -1)
            {
                ans += sum(pos);
                if(pos > 1) ans -= sum(pos - 1);
            }
            //if(ans - last) printf("%d %lld add %lld\n",i,now,ans - last);
            now *= k;
            if(now > MAX || now < -MAX) break;
            if(k == 1) break;
            if(k == -1 && now == 1) break;
        }
        add(get(p[i]),1);
    }
    cout << ans << endl;
    return 0;
}

