#define __ ios_base::sync_with_stdio(false);cin.tie(NULL);
using namespace std;

int n, k;
vector <int> skills;
vector <int> indices;
vector <int> skip;
vector <int> answer; 

void ReadInput ()
{
	cin >> n >> k;
	skills.resize(n);
	answer.resize(n);
	skip.resize(n);
	for (size_t i = 0; i < n; i++)	skip[i] = -2;
	indices.resize(n + 1);
	for (size_t i = 0; i < n; i++)	cin >> skills[i];
}

void Solve () 
{
	for(size_t i = 0; i < n; i++) indices[skills[i]] = i;
	int turn = 1;
	for(int i = n; i > 0; i--)
	{
		int next_index = indices[i];
		if (answer[next_index] != 0) continue;
		answer[next_index] = turn;

		int right_index = next_index + 1;
		int num_taken = 0;
		while (num_taken < k)
		{
			if (right_index == n) break;
			if (skip[right_index] == -2)
			{
				answer[right_index] = turn;
				num_taken++;
				right_index++;
			}
			else right_index = skip[right_index];
		}

		int left_index = next_index - 1;
		num_taken = 0;
		while (num_taken < k)
		{
			if (left_index == -1) break;
			if (skip[left_index] == -2)
			{
				answer[left_index] = turn;
				num_taken++;
				left_index--;
			}
			else left_index = skip[left_index]; 
		}
		skip [right_index - 1] = left_index;
		skip [left_index + 1] = right_index;

		if (turn == 1) turn = 2;
		else turn = 1;
	}

}

void WriteOutput ()
{
	for(size_t i = 0; i < answer.size(); i++)
		cout << answer[i];
}

int main ()
{__
	ReadInput ();
	Solve ();
	WriteOutput ();
	return 0;
}

