#include <bits/stdc++.h>
using namespace std;

template <class T> struct bit {
  int n;
  vector<T> tr;
  bit(int _n) : n(_n), tr(_n + 1) {}
  T qry(int x) {
    T ans{};
    while (x) {
      ans += tr[x];
      x -= x & -x;
    }
    return ans;
  }
  void modify(int x, T v) {
    while (x <= n) {
      tr[x] += v;
      x += x & -x;
    }
  }
};

int main() {
  cin.tie(0), ios::sync_with_stdio(0);

  int n, m, q;
  cin >> n >> m >> q;

  int star{};
  vector mp(n, string{});
  bit<int> g(n * m);

  for (int i = 0; i < n; ++i) {
    cin >> mp[i];
    for (int j = 0; j < m; ++j) {
      if (mp[i][j] == '*') {
        star += 1;
        g.modify(j * n + i + 1, 1);
      }
    }
  }

  for (int i = 0, x, y; i < q; ++i) {
    cin >> x >> y;
    x -= 1, y -= 1;

    if (mp[x][y] == '*') {
      star -= 1;
      mp[x][y] = '.';
      g.modify(y * n + x + 1, -1);
    } else {
      star += 1;
      mp[x][y] = '*';
      g.modify(y * n + x + 1, +1);
    }

    cout << star - g.qry(star) << "\n";
  }

  return 0 ^ 0;
}

