char str[5] = "AMID";
int dp[maxn][maxn];
int biao[maxn][maxn];
int n, m;
int cnt = 1;

int dfs(int x, int y, int need = 1) {
	biao[x][y] = cnt;
	dp[x][y] = 1;
	for(int k = 0; k < 4; k++) {
		int x1 = x + step[k][0], y11 = y + step[k][1];
		if(x1 < 0 || x1 >= n || y11 < 0 || y11 >= m)
			continue;
		if(str[need % 4] != mp[x1][y11])
			continue;
		if(dp[x1][y11] != -1) {
			if(biao[x1][y11] == cnt) {
				dp[x][y] = inf;
				return dp[x][y];
			}
		} else
			dfs(x1, y11, need + 1);
		dp[x][y] = max(dp[x][y], dp[x1][y11] + 1);
	}
	biao[x][y] = -1;
	return dp[x][y];
}
