        player_locked[i] = false;
        bfs_queue[i].push(SEP);
    }

    /// solve

    while (locked_players < p) {
        for (int i = 1; i <= p; i++) {
            for (int stg = 0; (!player_locked[i]) && (stg < stages_per_turn[i]); stg++) {
                expand_once(i);
