	edges[cnt].next = mat[x]; 
	mat[x] = &edges[cnt++]; 
}

queue<int> que; 
bool in_que[maxn]; 
int	 d[maxn]; 
void	spfa() 
{
	memset( d , -1 , sizeof(d) ); 
	memset( in_que, false , sizeof(in_que) ); 
	d[s] = 0;
	que.push(s); 
	while ( !que.empty() )
	{
		int i = que.front(); 
		que.pop(); 
		in_que[i] = false; 
		for ( Edge *p = mat[i]; p ; p =p->next )
		{
			int to = p->to; 
			if ( d[to] == -1 || d[to] > d[i]+p->w )
			{
				d[to] = d[i] + p->w; 
				if ( !in_que[to] )
				{
					in_que[to] = true; 
					que.push(to); 
				}
			}
		}
	}
}
