	for (int i = 1; i<=n; i++)
	{
		if ( d[i] > k ) continue; 
		if ( d[i] == k ) ans ++; 
		else 
		for ( Edge *p = mat[i]; p ; p = p->next )
		{
			int to = p->to; 
			if ( d[i] + p->w <= k ) continue; 
			int l = k-d[i]; 
