void compress() {
	vector<int> v (a, a + n);
	v.insert(v.end(), b, b + m);
	sort(v.begin(), v.end());
	v.erase(unique(v.begin(), v.end()), v.end());
	for(int i = 0; i < n; ++i) a[i] = lower_bound(v.begin(), v.end(), a[i]) - v.begin();
	for(int i = 0; i < m; ++i) b[i] = lower_bound(v.begin(), v.end(), b[i]) - v.begin();
}

int countInA[2 * N], countInB[2 * N];

void solve() {
	for(int i = 0; i < m; ++i) ++countInB[b[i]];
	vector<int> res;
	for(int i = 0; i < p && i < n; ++i) {
		int x = i;
		for(int y = i; y < n; y += p) {
			++countInA[a[y]];
			while(countInA[a[y]] > countInB[a[y]])
				--countInA[a[x]], x += p;
			if((y - x) / p == m - 1) res.push_back(x);
		}
		for(; x < n; x += p) --countInA[a[x]];
	}
