struct SegTree{
    vector<int>sg;
    void init(int n){sg.assign((n+1)<<2, 0);}
    void update(int u, int l, int r, int idx, int val){
        if(l > idx or r < idx) return;
        if(l == r){ sg[u] = val; return;}
        int mid = (l + r)>>1;
        update(u<<1, l, mid, idx, val);
        update(u<<1|1, mid + 1, r, idx, val);
        sg[u] = sg[u<<1] + sg[u<<1|1];
    }
    int get(int u, int l, int r, int x, int y){
        if(l > y or r < x) return 0;
        if(l >= x and r <= y) return sg[u];
        int mid = (l + r)>>1;
        int p1 = get(u<<1, l, mid, x, y);
        int p2 = get(u<<1|1, mid + 1, r, x, y);
        return p1 + p2;
    }
};
void solve(){
    int n, m, q; cin >> n >> m >> q;
    string s; cin >> s;
    s = '$' + s;
    map<int, int>mp;
    int c = 0;
    set<int>st;
    for(int i = 1; i <= n; i++) st.ins(i);
    for(int i = 1; i <= m; i++){
        int l, r; cin >> l >> r;
        auto itr = st.lower_bound(l);
        vector<int>v;
        for(auto i = itr; i != st.end() and *i <= r; i++){
            mp[*i] = ++c;
            v.pb(*i);
        }
        for(auto i: v) st.erase(i);
    }
    SegTree sg;
    sg.init(c);
    int cnt = 0;
    for(int i = 1; i <= n; i++){
        if(s[i] == '1'){
            cnt++;
            if(mp.count(i)) sg.update(1, 1, c, mp[i], 1);
        }
    }
    for(int i = 1; i <= q; i++){
        int idx; cin >> idx;
        if(!mp.count(idx)){
            if(s[idx] == '1'){ 
                cnt--;
                s[idx] = '0';
            }
            else{
                cnt++;
                s[idx] = '1';
            }
        }
        else{
            int p = mp[idx];
            if(s[idx] == '1'){ 
                cnt--;
                s[idx] = '0';
                sg.update(1, 1, c, p, 0);
            }
            else{
                cnt++;
                s[idx] = '1';
                sg.update(1, 1, c, p, 1);
            }
        }
        int p1 = min(cnt, c);
        int p = sg.get(1, 1, c, 1, p1);
        cout << p1 - p << ln;
    }
}
