int fac[128];
int exp[128];

int go(int loc, int v, int bound, int idx)
{
    if(!loc)
    {
        int ret = table[v] < bound;
        table[v] = idx;
        return ret;
    }
    else
    {
        int ret = 0;
        for(int j = 0; j <= exp[loc - 1]; j++, v *= fac[loc - 1])
            ret += go(loc - 1, v, bound, idx);
        return ret;
    }
}

