int qh, qt;
pii qu[N*N];
ll tot[N][N];
int dist[N][N];
int noise[N];

int main() {
  cin >> n >> m >> Q >> P;

  memset(G, '*', sizeof G);
  for(int i = 1; i <= n; i++) {
    scanf("%s", G[i] + 1);
    G[i][m+1] = '*';
  }

  memset(dist, -1, sizeof dist);

  for(int i = 1; i <= n; i++) 
    for(int j = 1; j <= m; j++) {
      if(!isalpha(G[i][j])) {
        continue;
      }

      noise[0] = Q * (G[i][j] - 'A' + 1);
      int l = 1;
