const int N = 200100;

int n, k;
int a[N];

bool calc(int l, int r, int num, int dat) {
	int cnt = 0;
	int last = -100;
	for (int i = l; i <= r; i ++)
		if (a[i] <= dat)
			if (i - last >= 2)
				last = i, cnt ++;
	return cnt >= num;
}

bool check(int x) {
	if ((k + 1) / 2 == k - (k + 1) / 2)
		return calc(1, n - 1, (k + 1) / 2, x) || calc(2, n, k - (k + 1) / 2, x);
	else
		return calc(1, n, (k + 1) / 2, x) || calc(2, n - 1, k - (k + 1) / 2, x);
}

int main() {
	n = read(), k = read();

	for (int i = 1; i <= n; i ++)
		a[i] = read();

	int l = 1, r = 1e9;

	while (l < r) {
		int mid = (l + r) / 2;
		if (check(mid)) r = mid; else l = mid + 1;
	}

	printf("%d\n", l);

	return 0;
}

