const int MN = 100005, inf = 1000000005, MOD = 1000000007;
const LL INF = 1000000000000000005LL;

int mask[MN], used[MN], primes[30];

int main()
{
	int n, pos = 0;
	scanf("%d", &n);
	for(int i = 2; i <= 70; ++i)
	{
		int ok = 1;
		for(int j = 2; j < i; ++j)
		{
			if(i % j == 0)
				ok = 0;
		}
		if(ok) primes[pos++] = i;
	}
	for(int i = 1; i <= n; ++i)
	{
		int a;
		scanf("%d", &a);
		for(int j = 0; j < pos; ++j)
		{
			while(a % primes[j] == 0)
			{
				mask[i] ^= (1 << j);
				a /= primes[j];
			}
		}
	}
	for(int j = 22; j >= 0; --j)
	{
		int cur = (1 << j), naj = -1;
		for(int i = 1; i <= n; ++i)
		{
			if(!used[i] && (mask[i] & cur))
			{
				if(naj == -1)
				{
					naj = mask[i];
					used[i] = 1;
				}
				else
				{
					mask[i] ^= naj;
				}
			}
		}
	}
	int res = 1;
	for(int i = 1; i <= n; ++i)
	{
		if(!mask[i])
		{
			res <<= 1;
			res %= MOD;
		}
	}
	printf("%d", (res - 1 + MOD) % MOD);
}

