const int N=2e5+10;
struct Point{
	int x,y;
}p[N];
inline bool operator<(const Point&t1,const Point&t2){
	return t1.y>t2.y||(t1.y==t2.y&&t1.x<t2.x);
}
int Ha[N],lh,T[N];
inline void qadd(int x){
	while (x<=lh) ++T[x],x+=lowbit(x);
}
inline int qsum(int x){
	int ans=0;
	while (x) ans+=T[x],x-=lowbit(x);
	return ans;
}
int tmp[N],lt,cnt[N],all;
int main(){
	int n=read();
	for (int i=1;i<=n;++i) p[i].x=read(),p[i].y=read(),Ha[++lh]=p[i].x;
	sort(Ha+1,Ha+lh+1);
	lh=unique(Ha+1,Ha+lh+1)-Ha-1;
	for (int i=1;i<=n;++i) p[i].x=lower_bound(Ha+1,Ha+lh+1,p[i].x)-Ha;
	sort(p+1,p+n+1);
	ll ans=0;
	for (int i=1,tp=1;i<=n;i=tp){
		tp=i;
		lt=0;
		while (tp<=n&&p[tp].y==p[i].y) tmp[++lt]=p[tp].x,++tp;
		for (int j=1;j<=lt;++j){
			int x=tmp[j];
			if (!cnt[x]) ++cnt[x],++all,qadd(x);
		}
		ll sum=1ll*all*(all+1ll)/2ll,lst=0;
		for (int j=1;j<=lt;++j){
			int x=tmp[j];
			ll now=qsum(x),d=now-lst-1;
			sum-=1ll*d*(d+1ll)/2ll;
			lst=now;
		}
		ll d=all-lst;
		sum-=1ll*d*(d+1ll)/2ll;
		ans+=sum;
	}
	cout<<ans<<'\n';
	return 0;
}

