struct sTree
{
	int h;
	int a[maxT],tag[maxT];

 	void init(const int n)
	 {
		for(h=1;(1<<h)<n+2;h++);
		fill(a,0);
	}

	void tagIt(const int &x,const int &c)
	{
		tag[x]+=c;
		a[x]+=c;
	}	 
	void relax(const int &x)
	{
		int y=(x<<1),z=y+1;
		if(tag[x])
		{
			tag[y]+=tag[x];tag[z]+=tag[x];
			a[y]+=tag[x];a[z]+=tag[x];
			tag[x]=0;
		}
	}

	void Pass_to_Leaf(int x)
	{
		repD(i,h-1)relax(x>>(i+1));
	}

	int Ask(int x)
	{
		x+=(1<<h);
		Pass_to_Leaf(x);
		return a[x];
	}

	void Add(int x,int y,int c)
	{
		int l=x+(1<<h)-1, r=y+(1<<h)+1;
		Pass_to_Leaf(l),Pass_to_Leaf(r);
		while(l+1<r)
		{
			if(!(l&1))tagIt(l^1,c);
			if(r&1)tagIt(r^1,c);
			l>>=1,r>>=1;
		}
		l=x+(1<<h)-1;
		r=y+(1<<h)+1;
	}
}T[2];

