		}



		int ans = inf; p = l = 0;

		for (int i = 0; i < m; i ++) {

			ans = min(ans, mrg(p, l, ln[i % 2][i]));

			p = mrg(p, l ++, (i == 0 ? a[i % 2][i] : a[i % 2][i] + 1));

			p = mrg(p, l ++, a[!(i % 2)][i] + 1);

		}

		cout << ans + 2 * m - 1 << fndl;

	}

	cout << endl;

	return 0;

}

