			Update_X(x);Update_Y(y);
		}
		else {
			x = read();y = read();
			ans = max(work(y,up[x],m),work(y,down[x],m));
			for (int i=1;i<=n;i++) len[i] = left[i][y];
			ans = max(ans,work(x,len,n));
			for (int i=1;i<=n;i++) len[i] = right[i][y];
			ans = max(ans,work(x,len,n));
			printf("%d\n",ans);
		}
	}
}

