int get(int x, int y, int a, int b) {
	if (y < a || b < x)
		return 0;
	return min(y, b) - max(x, a) + 1;
}

int getStart(int L, int R, int bit) {
	int start = L - 1;
	int end = R + 1;
	while (end - start > 1) {
		int mid = (end + start) >> 1;
		if (s[mid] & (1 << bit))
			end = mid;
		else
			start = mid;
	}
	return start;
}


long long solve(int L1, int R1, int L2, int R2, int req, int bit) {
	if (R1 < L1 || R2 < L2)
		return 0;
	if (bit < 0)
		return (R1 - L1 + 1) * 1LL * (R2 - L2 + 1);

	int start1 = getStart(L1, R1, bit), end1 = start1 + 1;
	int start2 = getStart(L2, R2, bit), end2 = start2 + 1;
	if (req & (1 << bit))
		return solve(L1, start1, end2, R2, req, bit - 1)
				+ solve(end1, R1, L2, start2, req, bit - 1);
	else
		return solve(L1, start1, L2, start2, req, bit - 1)
				+ solve(end1, R1, end2, R2, req, bit - 1)
				+ (start1 - L1 + 1) * 1LL * (R2 - end2 + 1)
				+ (start2 - L2 + 1) * 1LL * (R1 - end1 + 1);
}
