void dfs(int node , int dpth)
{
  dt[node]=++t;
  lvl[dpth].pb(t);
  depth[node]=dpth;
  for(int i=1 ; i<17 ; i++)
    par[node][i]=par[par[node][i-1]][i-1];
  int sz=adj[node].size();
  for(int i=0 ; i<sz ; i++)
    dfs(adj[node][i],dpth+1);
  ft[node]=t;
}

