bool sut(int j,int i)
{
  if((j-i)%2==0)
    {
      if(s[j]=='a' || s[j]=='?')return true;
      return false;
    }
  else if(s[j]=='b' || s[j]=='?')return true;
  return false;
}
int main()
{
  ios::sync_with_stdio(false);cin.tie(0);cout.tie(0);
  cin>>n>>s>>m;
  s='0'+s;
  int q=1;
  for(int i=1;i<=n;i+=2)
    {
      if(i>q)
	q=i,now=0;
      while(q<=n && sut(q,i))
	{
	  if(s[q]=='?')now++;
	  q++;
	  if(q-i==m)break;
	}
      //cout<<q<<endl;
      if(q-1<=n && q-i==m)can[i]=true,cost[i]=now;
      if(s[i]=='?')now--;
      if(i+1<=n && s[i+1]=='?')now--;
    }
  q=0;
  now=0;
  for(int i=2;i<=n;i+=2)
    {
      if(i>q)
	q=i,now=0;
      while(q<=n && sut(q,i))
	{
	  if(s[q]=='?')now++;
	  q++;
	  if(q-i==m)break;
	}
      //cout<<q<<endl;
      if(q-1<=n && q-i==m)can[i]=true,cost[i]=now;
      if(s[i]=='?')now--;
      if(i+1<=n && s[i+1]=='?')now--;
    }
  //for(int i=1;i<=n;i++)cout<<can[i]<<" ";cout<<endl;
  //dp

  for(int i=m;i<=n;i++)
    if(can[i-m+1])
      {
	if(dp[i-1]<dp[i-m]+1)
	  dp[i]=dp[i-m]+1,cdp[i]=cost[i-m+1]+cdp[i-m];
	else if(dp[i-1]==dp[i-m]+1)
	  dp[i]=dp[i-1],cdp[i]=min(cost[i-m+1]+cdp[i-m],cdp[i-1]);
	else
	  dp[i]=dp[i-1],cdp[i]=cdp[i-1];
	if(dp[i]>mx)
	  {
	    //cout<<i<<endl;
	    mx=dp[i];
	    ans=cdp[i];
	  }
	else if(dp[i]==mx)
