int calc(int v,int have,int need,int p,int son){
    if (have < 0)
        return 1<<29;
    if (son == -1){
        if (!have && !need)
            return 1<<29;
        return 0;
    }
    int& ans = dp[v][have][need][son];
    if (ans != -1)
        return ans;
    ans = 1<<29;
