#include <bits/stdc++.h>

using namespace std;

typedef long long ll;

const int N = 510;
char mat[N][N];
int rem[N];
ll pd[N][N];
int n;
ll mod;

ll solve(int l0, int l1)
{
	if (l0 < 0 or l1 < 0)
		return 0LL;

	if (l0 == 0 and l1 == 0)
		return 1LL;

	if (pd[l0][l1] != -1)
		return pd[l0][l1];

	ll &ret = pd[l0][l1];

	ll ll0 = l0, ll1 = l1;
	ll l0c2 = ((ll0 * (ll0-1LL)/2LL))%mod;
	ll l1c2 = ((ll1 * (ll1-1LL)/2LL))%mod;

	ret = (l0c2*solve(l0-2, l1+2))%mod + (l1c2*solve(l0, l1-2))%mod + (ll1*ll0*solve(l0-1, l1))%mod;
	ret %= mod;
	return ret;	
}

int main()
{
	int m;
	scanf("%d %d %lld", &n, &m, &mod);
	for (int i = 0; i < m; i++)
	{
		scanf("%s", mat[i]);
	}
	int l0 = 0, l1 = 0;
	for (int j = 0; j < n; j++)
	{
		rem[j] = 2;
		for (int i = 0; i < m; i++)
		{
			if (mat[i][j] == '1')
				rem[j]--;
		}
		if (rem[j] == 2)
			l0++;
		else if (rem[j] == 1)
			l1++;
	}
	memset(pd, -1, sizeof(pd));
	printf("%lld\n", solve(l0, l1));
	return 0;
}

