typedef long long int ll;

BIT<int> bit[4][11][11];
char S[100009];

int c2i(char c)
{
    switch(c)
    {
        case 'A': return 0;
        case 'T': return 1;
        case 'G': return 2;
        default: return 3;
    }
}

int main()
{
    RD(S);
    int N = strlen(S);

    for(int c: RG(4))
        for(int l: RG(1, 11))
            for(int m: RG(l))
                bit[c][l][m] = BIT<int>((N + l - 1)/ l);


    for(int i: RG(N))
    {
        S[i] = c2i(S[i]);
        for(int l: RG(1, 11))
            bit[S[i]][l][i % l].update(i / l, 1);
    }

    int Q;
    RD(Q);
    while(Q--)
    {
        int t;
        RD(t);
        if(t == 1)
        {
            int i;
            char c;
            RD(i, c);
            c = c2i(c);
            i--;
            if(S[i] == c)continue;

            for(int l: RG(1, 11))
            {
                bit[S[i]][l][i % l].update(i / l, -1);
                bit[c][l][i % l].update(i / l, 1);
            }
            S[i] = c;
        }
        else
        {
            int l, r;
            char buf[32];
            RD(l, r, buf);
            l--, r--;
            int len = strlen(buf);
            int ans = 0;
            for(int i: RG(len))
            {
                if(l + i > r)break;
                int m = (l + i) % len;
                ans += bit[c2i(buf[i])][len][m].query((l + i) / len, (r - (l + i)) / len + (l + i) / len + 1);
            }

            WTL(ans);
        }
    }
}

