struct Node{
	ll s[N];
	int m[N],x[N];
};
int f[N],w[N],n;
Node res,ans,tmp;
void mul(Node& A,Node& B){
	int a;
	for(int i=0;i<n;++i){
		tmp.x[i]=B.x[i];tmp.s[i]=B.s[i];tmp.m[i]=B.m[i];
	}
	for(int i=0;i<n;++i){
		a=A.x[i];A.x[i]=tmp.x[a];
		A.s[i]=A.s[i]+tmp.s[a];
		if(A.m[i]!=-1) A.m[i]=min(A.m[i],tmp.m[a]);
		else A.m[i]=tmp.m[a];
	}
}
void solve(ll k){
	for(int i=0;i<n;++i){
		ans.x[i]=i;res.x[i]=f[i];
		ans.s[i]=0;res.s[i]=(ll)w[i];
		ans.m[i]=-1;res.m[i]=w[i];
	}
	while(k){
		if(k&1) mul(ans,res);
		mul(res,res);k>>=1;
	}
}
