	ll k;
	while(~scanf("%d%lld",&n,&k)){
		for(int i=0;i<n;++i) scanf("%d",&f[i]);
		for(int i=0;i<n;++i) scanf("%d",&w[i]);
		solve(k);
		for(int i=0;i<n;++i){
			printf("%lld %d\n",ans.s[i],ans.m[i]);
		}
	}
	return 0;
}

