#define all(x) (x).begin(), (x).end()

template<class T> struct BIT {
    int n;
    vector<T> bit;

    BIT(int sz) { bit.resize(n = sz + 7); }

    void upd(int i, T x) { 
        for(i++; i < n; i += i & -i) bit[i] += x;
    }

    T query(int i) {
        int ret = 0;
        for(i++; i > 0; i -= i & -i) ret += bit[i];
        return ret;
    }

    T query(int l, int r) { return (l > r ? 0 : query(r) - query(l - 1)); };
};

int main() {
    cin.tie(0)->sync_with_stdio(false);

    int n, q;
    cin >> n >> q;

    string s;
    cin >> s;

    set<int> a;
    set<int, greater<>> b;
    auto check = [&](int i, int t) {
        if(i < 0 || i + 1 >= n || s[i] != s[i + 1])
            return;

        if(s[i] == '(') {
            if(t)
                a.insert(i);
            else
                a.erase(i);
        }
        else {
            if(t)
                b.insert(i);
            else
                b.erase(i);
        }
    };

    BIT<int> bit(n);
    for(int i = 0; i < n; i++) {
        bit.upd(i, (s[i] == '(' ? 1 : -1));
        check(i, 1);
    }

    while(q--) {
        int i;
        cin >> i;
        i--;

        if(s[i] == '(')
            bit.upd(i, -2);
        else
            bit.upd(i, 2);

        check(i, 0), check(i - 1, 0);
        s[i] ^= '(' ^ ')';
        check(i, 1), check(i - 1, 1);

        if(n % 2)
            cout << "NO" << '\n';
        else {
            bool ok = 1;
            if((a.empty() && bit.query(0, n) < 0) || (a.size() && bit.query(0, *a.begin() - 1) < 0))
                ok = 0;
            if((b.empty() && bit.query(0, n) > 0) || (b.size() && bit.query(*b.begin() + 2, n) > 0))
                ok = 0;
            if(s[0] == ')' || s[n - 1] == '(')
                ok = 0;

            cout << (ok ? "YES" : "NO") << '\n';
        }
    }

    return 0;
}

