void trans(int *f, int fl, int fr, int *g, int gl, int gr) {
	if(gl >= gr) return;
	int m = (gl + gr) / 2;
	int cnt = 0;
	int j = -1, k = -1;
	int b = Get(root[m + 1], 1, n, max(fl, 1), m);
	for(int i = fl; i < min(fr, m); i ++) {
		if(i && p[i] > m) b --;
		int t = f[i] + b;
		if(t > k) {
			j = i; k = t;
		}
	}
	g[m] = k;
	trans(f, fl, j + 1, g, gl, m);
	trans(f, j, fr, g, m + 1, gr);
}

