template <typename T>

class Fenwick { // 1 <= pos <= n

 public:

  int n;

  vector<T> tree;

  Fenwick(const int &n) : n(n), tree(n, -1E9) {}

  inline void modify(int pos, T x) {

    for ( ; pos <= n; pos += pos & -pos) {

      tree[pos - 1] = max(tree[pos - 1], x);

    }

  }

  inline T get(int pos) {

    T res = -1E9;

    for ( ; pos > 0; pos -= pos & -pos) {

      res = max(res, tree[pos - 1]);

    }

    return res;

  }

};



