void add(string s) {
	int cur = root;
	for (int i = 0; i < sz(s); i++) {
		if (!t[cur].nxt.count(s[i])) t[cur].nxt[s[i]] = ++sz;
		cur = t[cur].nxt[s[i]];
	}
	t[cur].is_t = true;
	st[cur].insert(sz(s));
}

void dfs(int v, int len) {
	for (auto pr : t[v].nxt) {
		int to = pr.s;
		dfs(to, len + 1);
		for (auto x : st[to])
			st[v].insert(x);
	}
	if (!t[v].is_t && v > 0) {
		auto it = st[v].end();
		it--;
		ans -= *it;
		ans += len;
		st[v].erase(it);
		st[v].insert(len);
	}
}

