int Bfs(int x, int& y)
{
	int res = -1;
	memset(vis, 0, sizeof(vis));
	memset(last, 0, sizeof(last));
	Node A, B;
	A.n = x; A.d = 0;
	vis[x] = 1;
	q.push(A);
	while (!q.empty())
	{
		A = q.front(); q.pop();
		if (flag[A.n])
		{
			if (res < A.d || y > A.n) y = A.n;
			res = A.d;
		}
		for (int i = 0; i < f[A.n].size(); i++)
		{
			B.n = f[A.n][i];
			B.d = A.d + 1;
			if (!vis[B.n])
			{
				last[B.n] = A.n;
				q.push(B);
				vis[B.n] = 1;
			}
		}
	}
	return res;
}

int Dfs(int x)
{
	if (last[x] == 0) return 0;
	int res = Dfs(last[x]) + 1;
	last[x] = 0;
	return res;
}

