int solve(int l,int r)

{

	if(l>r) return 0;

	if(l==r) return min(a[l],1);

	int minn=inf,tmp;

	for(int i=l;i<=r;i++)

	{

		if(minn>a[i])

		{

			minn=a[i];

			tmp=i;

		}

	}

	for(int i=l;i<=r;i++) a[i]-=minn;

	return min(r-l+1,solve(l,tmp-1)+solve(tmp+1,r)+minn);

}



