inline long long work(long long b,long long x){
	if(x==0) return 0;
	int m=0;
	while(x>0){
		m++;
		c[m]=x%b;
		x=x/b;
	}
	long long tmp=0;
	for(int i=1;i<c[m];i++) tmp+=g[b][m-1][1<<i];
	for(int i=1;i<m;i++) tmp+=f[b][i][0];
	long long now=1<<c[m];
	for(int i=m-1;i>0;i--){
		for(int j=0;j<c[i];j++) tmp+=g[b][i-1][now^(1<<j)];
		now^=1<<c[i];
	}
	if(now==0) tmp++;
	return tmp;
}

