int A[SZ];

int count(int msk) {
	int rez = 0;

	for(int j = 0; j < N; ++j)
		rez += (msk >> j) & 1;

	return rez;
}

void solve() {
	string str;
	cin >> str;

	int n = len(str);
	int answ = 0;

	for(int i = 0; i < n; ++i) {
		int msk = 0;

		for(int j = i; j < n; ++j) {
			int code = str[j] - 'a';

			if((msk >> code) & 1)
				break;

			msk |= (1 << code);
			A[msk] = count(msk);
			answ = (A[msk] > answ ? A[msk] : answ);
		}
	}

	for(int j = 0; j < N; ++j) {
		for(int msk = 0; msk < (1 << N); ++msk) {
			int bit = 1 << j;

			if(msk & bit) {
				A[msk] = (A[msk ^ bit] > A[msk] ? A[msk ^ bit] : A[msk]);
			}
		}
	}

	for(int msk = 0; msk < (1 << N); ++msk) {
		int msk2 = ((1 << N) - 1) & (~msk);
		int value = A[msk] + A[msk2];

		answ = (value > answ ? value : answ);
	}

	cout << answ << '\n';
}

