typedef long long ll;
typedef pair<int,int> pii;

const int MAXn = 2e5+10;
const int INF = 2e9+1000;
int p[MAXn], l[MAXn];
vector<pii> Q[MAXn];
int ans[MAXn];
int n;

int tree[MAXn];
int rval[MAXn];
void tree_inc(int ind, int val) {
	rval[ind] += val;
	ind++;
	while(ind <= n) {
		tree[ind] += val;
		ind += (ind & -ind);
	}
}
int tree_sum(int ind) {
	int sum = 0;
	ind++;
	while(ind > 0) {
		sum += tree[ind];
		ind -= (ind&-ind);
	}
	return sum;
}

vector<pii> v;
void add(int l, int r) {
	while(!v.empty() && v.back().first <= r) {
		r = max(r, v.back().second);
		tree_inc(v.size()-1, -rval[v.size()-1]);
		v.pop_back();
	}
	v.push_back(pii(l, r));
	tree_inc(v.size()-1, r-l);
}

int query(int l, int r) {
	int ind = upper_bound(v.begin(), v.end(), pii(r, INF), greater<pii>())-v.begin();
	return r-l-(tree_sum(v.size()-1) - tree_sum(ind) + (r-v[ind].first));
}

