            C[i][j]=(C[i-1][j-1]+C[i-1][j])%Mod;

    for(int i=1;i<=n;i++)

    {

        for(int j=1;j<=n;j++) 

            S[i]+=(max(abs(X[i]-X[j]),abs(Y[i]-Y[j]))<=R);

        int res=(C[n][m]+Mod-C[n-S[i]][m])%Mod;

        ans=(ans+res*(w[i]*w[i]%Mod)%Mod)%Mod;

    }

    for(int i=1;i<n;i++)

    {

        for(int j=i+1;j<=n;j++)

        {

            int T=Count(i,j),A=S[i]-T,B=S[j]-T,D=n-(A+B+T);

            int res=(C[n][m]+C[D][m])%Mod;

            res=(res+(Mod-(C[A+D][m]+C[B+D][m])%Mod))%Mod;

            ans=(ans+(res*2)*(w[i]*w[j]%Mod)%Mod)%Mod;

        }

    }

    cout<<ans<<'\n';

    return 0;

}

