void bd(int x,int y){
	qd[++CE]=y;
	qn[CE]=l[x];
	l[x]=CE;
}

void dfs(int x,int y){
	v[x]=1;
	p[x]=y;	
	for (int k=l[x];k;k=qn[k])
		if (!v[qd[k]]){
			dfs(qd[k],y);
			dp[x]+=dp[qd[k]];
		}
	dp[x]+=s[x];
}

int find(int x){
	if (x==f[x]) return x;
	else return f[x]=find(f[x]);
}

