		for (int j=x;j<=y;j++)
			if (!v[ta[j]])
				dfs(ta[j],ta[j]);

		for (int j=x;j<=y;j++){

			w=min(dp[ta[j]],dp[tb[j]]);

			E[j].AC=2*w*(dp[p[ta[j]]]-w);

			if (E[j].AC>AC) AC=E[j].AC;			

			a=find(E[j].x);
			b=find(E[j].y);

			s[a]+=s[b];
			f[b]=a;
