	vec s(d,u);
	for(edge*i=h[u];i;i=i->s)
		if(i->v^f&&!v[i->v])
			s=max(s,dfs1(i->v,u,d+i->w));
	return s;
}
vec dfs2(int u){
	vec s(d[u],u);
	for(edge*i=h[u];i;i=i->s)
		if(i->v^p[u]){
			d[i->v]=d[p[i->v]=u]+i->w;
			r[i->v]=i->w;
			s=max(s,dfs2(i->v));
