struct node {
	int mx, cnt, lz;
	node() {
		mx = cnt = lz = 0;	
	}
} x[N << 2];

void build(int l = 0, int r = n, int v = 1) {
	x[v].lz = 0;
	if(r - l < 2) {
		x[v].mx = l, x[v].cnt = 1;
		return;
	}
	int mid = (l + r) >> 1;
	build(l, mid, 2 * v), build(mid, r, 2 * v + 1);
	x[v].mx = x[2 * v + 1].mx, x[v].cnt = 1;
}
void put(int l, int r, int v) {
	if(x[v].lz == 0) return;
	int cur = x[v].lz;
	x[2 * v].mx += cur, x[2 * v].lz += cur;
	x[2 * v + 1].mx += cur, x[2 * v + 1].lz += cur;
	x[v].lz = 0;
}
node merge(node a, node b) {
	node res = a;
	if(b.mx == res.mx) res.cnt += b.cnt;
	else if(b.mx > res.mx) res = b;
	res.lz = 0;
	return res;
}
void change(int l, int r, int s, int e, int val, int v) {
	if(r <= s || l >= e) return;
	if(l >= s && r <= e) {
		x[v].mx += val, x[v].lz += val;
		return;
	}
	put(l, r, v);
	int mid = (l + r) >> 1;
	change(l, mid, s, e, val, 2 * v), change(mid, r, s, e, val, 2 * v + 1);

	x[v] = merge(x[2 * v], x[2 * v + 1]);
}
node get(int l, int r, int s, int e, int v) {
	node res;
	if(r <= s || l >= e) return res;
	if(l >= s && r <= e) return x[v];
	put(l, r, v);
	int mid = (l + r) >> 1;
	node a = get(l, mid, s, e, 2 * v), b = get(mid, r, s, e, 2 * v + 1);

	return merge(a, b);
}

