const int mod = 1e9 + 7;

int query, x, xx, y, yy, k;

typedef long long LL;

typedef pair <LL, LL> PLL;

int mex(int x){
	return 1 << (31 - __builtin_clz(x));
}


PLL dfs(int x, int y, int bit){

	if(bit == 0) return make_pair(0ll, 0ll);
	if(x == 0) return make_pair(0ll, 0ll);
	if(y == 0) return make_pair(0ll, 0ll);

	if(x > y) swap(x, y);

	int z = mex(y);
	int bit1 = min(z, bit);

	LL gas = 0, ans = 0;

	if(z > x){

		ans = (((LL)bit1 * (bit1 + 1) / 2) % mod) * x % mod;
		gas = (LL)bit1 * x % mod;

		PLL tmp = dfs(x, y - z, max(bit - z, 0));

		ans = (ans + tmp.first + tmp.second * z) % mod;
		gas = (gas + tmp.second) % mod;

	}

	else{

		ans = (((LL)bit1 * (bit1 + 1) / 2) % mod) * z % mod;
		gas = (LL)bit1 * z % mod;
		///cout << ans << endl;

		PLL tmp = dfs(x - z, y - z, bit);

		ans = (ans + tmp.first) % mod;
		gas = (gas + tmp.second) % mod;

		tmp = dfs(z, y - z, max(bit - z, 0));

		ans = (ans + tmp.first + tmp.second * z) % mod;
		gas = (gas + tmp.second) % mod;

		tmp = dfs(x - z, z, max(bit - z, 0));

		ans = (ans + tmp.first + tmp.second * z) % mod;
		gas = (gas + tmp.second) % mod;
	}

	return make_pair(ans, gas);
}

