		ans = (ans + tmp.first) % mod;

		tmp = dfs(x - 1, y - 1, k);
		ans = (ans + tmp.first) % mod;

		tmp = dfs(x - 1, yy, k);
		ans = (ans + mod - tmp.first) % mod;

		tmp = dfs(xx, y - 1, k);
		ans = (ans + mod - tmp.first) % mod;

