void FWT(LL a[],int l,int r)
{
	if(l == r) return;
	int m = (l+r) >> 1;
	FWT(a,l,m); FWT(a,m+1,r);
	for(int i=0;i<=m-l;++i)
	{
		LL a0 = a[l+i],a1 = a[m+i+1];
		a[l+i] = a0 + a1;
		a[m+i+1] = a0 - a1;
	}
}

void IFWT(LL a[],int l,int r)
{
	if(l == r) return;
	int m = (l+r) >> 1;
	for(int i=0;i<=m-l;++i)
	{
		LL a0 = a[l+i],a1 = a[m+i+1];
		a[l+i] = (a0 + a1)/2;
		a[m+i+1] = (a0 - a1)/2;
	}
	IFWT(a,l,m); IFWT(a,m+1,r);
}

