using namespace std;

const int N = 1e5 + 5;
const int MOD = 1e9 + 7;

int n, nq;
int f[N], g[N], h[N];
int ans[57][57], cnt[57];
char s[N];

namespace {
  int fac[N], ifac[N];
  int Add(int a, int b) { return (a += b) >= MOD? a - MOD : a; }
  int Sub(int a, int b) { return (a -= b) < 0? a + MOD : a; }
  int Mul(int a, int b) { return (long long)a * b % MOD; }
  int Pow(int a, int b) {
    int r = 1;
    for (; b; b >>= 1, a = Mul(a, a)) if (b & 1) r = Mul(r, a);
    return r;
  }
  void Math_Init() {
    fac[0] = 1;
    for (int i = 1; i < N; ++i) {
      fac[i] = Mul(fac[i - 1], i);
    }
    ifac[N - 1] = Pow(fac[N - 1], MOD - 2);
    for (int i = N - 2; ~i; --i) {
      ifac[i] = Mul(ifac[i + 1], i + 1);
    }
  }
}

int Ex(char c) {
  if (c >= 'a' && c <= 'z') {
    return c - 'a' + 1;
  } else {
    return c - 'A' + 27;
  }
}

void Back(int *f, int *g, int k) {
  k = cnt[k];
  for (int i = 0; i <= n / 2; ++i) {
    if (i < k) {
      g[i] = f[i];
    } else {
      g[i] = Sub(f[i], g[i - k]);
    }
  }
}

void print(int *f) {
  for (int i = 0; i <= n / 2; ++i) {
    cerr << f[i] << ' ';
  }
  cerr << endl;
}

int main() {
  Math_Init();
  scanf("%s", s + 1);
  n = strlen(s + 1);
  for (int i = 1; i <= n; ++i) {
    ++cnt[Ex(s[i])];
  }

  f[0] = 1;
  for (int i = 1; i <= 52; ++i) {
    if (!cnt[i]) {
      continue;
    }
    for (int j = n / 2; j >= cnt[i]; --j) {
      f[j] = Add(f[j], f[j - cnt[i]]);
    }
  }

  //cerr << "good." << endl;

  //print(f);

  for (int i = 1; i <= 52; ++i) {
    for (int j = 1; j <= 52; ++j) {
      if (!cnt[i] || !cnt[j]) {
        continue;
      }
      Back(f, g, i);
      if (i != j) {
        Back(g, h, j);
        //print(h);
        ans[i][j] = h[n / 2];
      } else {
        //print(g);
        ans[i][j] = g[n / 2];
      }
    }
  }

  int con = Mul(fac[n / 2], fac[n / 2]);
  for (int i = 1; i <= 52; ++i) {
    con = Mul(con, ifac[cnt[i]]);
  }
  con = Mul(con, 2);
  //cerr << "con : " << con << endl;

  scanf("%d", &nq);
  for (int x, y; nq--; ) {
    scanf("%d%d", &x, &y);
    x = Ex(s[x]);
    y = Ex(s[y]);
    printf("%d\n", Mul(con, ans[x][y]));
  }

  return 0;
}

